#include "PSXInputMapper.h"
PSXInputMapper::PSXInputMapper(const PSXInputConfig& config):_config(config){}
PSXInputState PSXInputMapper::map(const PSXControllerState& raw) const { PSXInputState out{}; out.buttons=raw.buttons; out.hat=mapHat(raw.buttons); out.leftX=mapAxis(raw.leftX,false); out.leftY=mapAxis(raw.leftY,_config.invertLeftY); out.rightX=mapAxis(raw.rightX,false); out.rightY=mapAxis(raw.rightY,_config.invertRightY); out.l2=raw.pressureL2; out.r2=raw.pressureR2; return out; }
void PSXInputMapper::setConfig(const PSXInputConfig& config){_config=config;} const PSXInputConfig& PSXInputMapper::config() const{return _config;}
int8_t PSXInputMapper::mapAxis(uint8_t value,bool invert) const { int16_t v=static_cast<int16_t>(value)-128; if(abs(v)<=_config.deadZone)v=0; else { int16_t sign=v<0?-1:1; v=sign*((abs(v)-_config.deadZone)*127/(128-_config.deadZone)); } if(invert)v=-v; return static_cast<int8_t>(constrain(v,-127,127)); }
uint8_t PSXInputMapper::mapHat(uint16_t b) const { bool u=b&(1u<<static_cast<uint8_t>(PSXButton::Up)); bool r=b&(1u<<static_cast<uint8_t>(PSXButton::Right)); bool d=b&(1u<<static_cast<uint8_t>(PSXButton::Down)); bool l=b&(1u<<static_cast<uint8_t>(PSXButton::Left)); if(u&&!r&&!l)return 0; if(u&&r)return 1; if(r&&!u&&!d)return 2; if(d&&r)return 3; if(d&&!r&&!l)return 4; if(d&&l)return 5; if(l&&!u&&!d)return 6; if(u&&l)return 7; return 8; }
